function safe(fn){try{return fn();}catch{return undefined;}}
function now(){return system.currentTick;} function level(p){return safe(()=>p.level)??0;}
function cls(p){if(safe(()=>p.hasTag("geumyi_class_sword")))return"sword";if(safe(()=>p.hasTag("geumyi_class_archer")))return"archer";if(safe(()=>p.hasTag("geumyi_class_mage")))return"mage";if(safe(()=>p.hasTag("geumyi_class_cleric")))return"cleric";if(safe(()=>p.hasTag("geumyi_class_berserker")))return"berserker";if(safe(()=>p.hasTag("geumyi_class_assassin")))return"assassin";if(safe(()=>p.hasTag("geumyi_class_fighter")))return"fighter";if(safe(()=>p.hasTag("geumyi_class_hero")))return"hero";if(safe(()=>p.hasTag("geumyi_class_reaper")))return"reaper";if(safe(()=>p.hasTag("geumyi_class_sheriff")))return"sheriff";return"none";}
function cname(c){return c==="sword"?"검사":c==="archer"?"궁수":c==="mage"?"마법사":c==="cleric"?"성직자":c==="berserker"?"광전사":c==="assassin"?"암살자":c==="fighter"?"격투가":c==="hero"?"용사":c==="reaper"?"사신":c==="sheriff"?"보안관":"미전직";}
function msg(p,t){safe(()=>p.sendMessage(t));}
function bar(p,t,duration=100){
  const seq=(skillUiSeq.get(p.id)??0)+1; skillUiSeq.set(p.id,seq); skillUiUntil.set(p.id,now()+duration);
  safe(()=>{p.addTag("geumyi_skill_ui_lock");p.onScreenDisplay.setActionBar(t);});
  system.runTimeout(()=>{if(skillUiSeq.get(p.id)!==seq)return;skillUiUntil.delete(p.id);safe(()=>p.removeTag("geumyi_skill_ui_lock"));},duration);
}
function activeSkill(p){return activeSkillCast.get(p.id);}
function skillBusy(p){const st=activeSkill(p);if(!st)return false;bar(p,`§c${st.name} 시전 중입니다. 다른 스킬은 아직 사용할 수 없습니다.`);return true;}
function beginActiveSkill(p,id,name=SKILLS[id]?.name??id){activeSkillCast.set(p.id,{id,name});}
function endActiveSkill(p,id){const st=activeSkillCast.get(p.id);if(!st||!id||st.id===id)activeSkillCast.delete(p.id);}
function key(p,s){return`${p.id}:${s}`;} function cdTicks(p,s){return Math.max(0,(cooldowns.get(key(p,s))??0)-now());} function cdLeft(p,s){return Math.max(0,Math.ceil(cdTicks(p,s)/20));} function startCd(p,s,sec){cooldowns.set(key(p,s),now()+Math.round(sec*20));}
function dist(a,b){const x=a.x-b.x,y=a.y-b.y,z=a.z-b.z;return Math.sqrt(x*x+y*y+z*z);} function horizView(p){const v=p.getViewDirection(),l=Math.hypot(v.x,v.z)||1;return{x:v.x/l,y:0,z:v.z/l};}
function particle(dim,id,loc){safe(()=>dim.runCommand(`particle ${id} ${loc.x.toFixed(2)} ${loc.y.toFixed(2)} ${loc.z.toFixed(2)}`));}
function sound(p,id,pitch=1,vol=1){safe(()=>p.playSound(id,{volume:vol,pitch}));}
function areaSound(p,id,pitch=1,vol=1,r=48,loc){const c=loc??p.location;for(const q of world.getAllPlayers()){try{if(q.dimension.id!==p.dimension.id||dist(q.location,c)>r)continue;q.playSound(id,{volume:vol,pitch});}catch{}}}
function isAirLike(id){return id==="minecraft:air"||id==="minecraft:cave_air"||id==="minecraft:void_air"||id==="minecraft:water"||id.includes("grass")||id.includes("flower")||id.includes("fern");}
function targetable(e){try{if(!e||e.typeId==="minecraft:player")return false;const x=["minecraft:armor_stand","minecraft:villager","minecraft:villager_v2","minecraft:wandering_trader","minecraft:npc","minecraft:item","minecraft:xp_orb","minecraft:painting","geumyi:reaper_soul","geumyi:reaper_scythe_projectile","geumyi:reaper_massacre_orbit"];if(x.includes(e.typeId)||e.typeId.includes("arrow")||e.typeId.includes("projectile"))return false;return!!e.getComponent("minecraft:health");}catch{return false;}}
function damage(e,n,p,cause=EntityDamageCause.entityAttack){if(!targetable(e)||!Number.isFinite(n)||n<=0)return false;return!!safe(()=>e.applyDamage(n,{cause,damagingEntity:p}));}
function projectileDamage(e,n,p,a){if(!targetable(e)||!Number.isFinite(n)||n<=0)return false;return!!safe(()=>e.applyDamage(n,{cause:EntityDamageCause.entityAttack,damagingEntity:p}));}
function clericTarget(e){try{if(!e||e.typeId==="minecraft:player")return false;const x=["minecraft:armor_stand","minecraft:npc","minecraft:item","minecraft:xp_orb","minecraft:painting","geumyi:reaper_soul","geumyi:reaper_scythe_projectile","geumyi:reaper_massacre_orbit"];if(x.includes(e.typeId)||e.typeId.includes("arrow")||e.typeId.includes("projectile"))return false;return!!e.getComponent("minecraft:health");}catch{return false;}}
function clericDamage(e,n,p,cause=EntityDamageCause.entityAttack){if(!clericTarget(e)||!Number.isFinite(n)||n<=0)return false;return!!safe(()=>e.applyDamage(n,{cause,damagingEntity:p}));}
function clericProjectileDamage(e,n,p){if(!clericTarget(e)||!Number.isFinite(n)||n<=0)return false;return!!safe(()=>e.applyDamage(n,{cause:EntityDamageCause.entityAttack,damagingEntity:p}));}
function trialBarRise(e,ominous=false){const id=ominous?"minecraft:trial_spawner_detection_ominous":"minecraft:trial_spawner_detection";for(let i=0;i<6;i++)system.runTimeout(()=>{try{const l=e.location;particle(e.dimension,id,{x:l.x,y:l.y+.15+i*.34,z:l.z});}catch{}},i*2);}
function health(e){return safe(()=>e.getComponent("minecraft:health")?.currentValue)??-1;}
function topTargets(p,r,c){return p.dimension.getEntities({location:p.location,maxDistance:r}).filter(targetable).sort((a,b)=>health(b)-health(a)).slice(0,c);}
function targetPoint(e){const h=safe(()=>e.getHeadLocation());if(h)return{x:h.x,y:h.y-.35,z:h.z};return{x:e.location.x,y:e.location.y+1.0,z:e.location.z};}
function holyRing(dim,center,r,count=12,y=.35){for(let i=0;i<count;i++){const a=i*Math.PI*2/count,id=i%3===0?"minecraft:villager_happy":"minecraft:endrod";particle(dim,id,{x:center.x+Math.cos(a)*r,y:center.y+y,z:center.z+Math.sin(a)*r});}}
function holySphereShell(dim,center,r,count=10,phase=0){for(let i=0;i<count;i++){const u=(i+.5)/count,phi=Math.acos(1-2*u),theta=i*2.399963229728653+phase,id=i%4===0?"minecraft:villager_happy":"minecraft:endrod";particle(dim,id,{x:center.x+r*Math.sin(phi)*Math.cos(theta),y:center.y+1+r*Math.cos(phi),z:center.z+r*Math.sin(phi)*Math.sin(theta)});}}
function giveClericShieldAbsorption14(a,duration){safe(()=>a.addEffect("absorption",duration,{amplifier:3,showParticles:false}));let hadUlt=false;try{hadUlt=!!safe(()=>a.hasTag("geumyi_sword_ult"));if(hadUlt)safe(()=>a.removeTag("geumyi_sword_ult"));damageBypass.add(a.id);a.applyDamage(2);}catch{}finally{damageBypass.delete(a.id);if(hadUlt)safe(()=>a.addTag("geumyi_sword_ult"));}}
