function coneTargets(p,r,deg){const v=horizView(p),cs=Math.cos((deg/2)*Math.PI/180),out=[];for(const e of p.dimension.getEntities({location:p.location,maxDistance:r+1.2})){if(!targetable(e))continue;const dx=e.location.x-p.location.x,dz=e.location.z-p.location.z,l=Math.hypot(dx,dz);if(l<.05||l>r+.8)continue;if((dx/l)*v.x+(dz/l)*v.z>=cs)out.push(e);}return out;}
function assassinWhoosh(p){sound(p,"mob.endermen.portal",1.7,.42);system.runTimeout(()=>sound(p,"random.bow",1.9,.28),1);}
function assassinStealthed(p){return cls(p)==="assassin"&&!!safe(()=>p.getEffect("invisibility"));}
function isBehindTarget(attacker,target){try{const f=target.getViewDirection(),dx=attacker.location.x-target.location.x,dz=attacker.location.z-target.location.z,l=Math.hypot(dx,dz)||1;return f.x*(dx/l)+f.z*(dz/l)<-.5;}catch{return false;}}
function nearestTarget(p,r=24,exclude=new Set()){return p.dimension.getEntities({location:p.location,maxDistance:r}).filter(e=>targetable(e)&&!exclude.has(e.id)&&health(e)>0).sort((a,b)=>dist(p.location,a.location)-dist(p.location,b.location))[0];}
function strongestTarget(p,r=24,exclude=new Set()){return p.dimension.getEntities({location:p.location,maxDistance:r}).filter(e=>targetable(e)&&!exclude.has(e.id)&&health(e)>0).sort((a,b)=>{const d=health(b)-health(a);return Math.abs(d)>.01?d:dist(p.location,a.location)-dist(p.location,b.location);})[0];}
function teleportBehind(p,target){try{const f=target.getViewDirection(),hl=targetPoint(target),side={x:-f.z,z:f.x},base=target.location;const tries=[{x:base.x-f.x*1.65,y:base.y+.05,z:base.z-f.z*1.65},{x:base.x-f.x*1.25+side.x*.65,y:base.y+.05,z:base.z-f.z*1.25+side.z*.65},{x:base.x-f.x*1.25-side.x*.65,y:base.y+.05,z:base.z-f.z*1.25-side.z*.65},{x:base.x-f.x*1.25,y:base.y+1.05,z:base.z-f.z*1.25}];for(const pos of tries){if(safe(()=>p.tryTeleport(pos,{dimension:target.dimension,facingLocation:hl,checkForBlocks:true})))return true;}safe(()=>p.teleport(tries[0],{dimension:target.dimension,facingLocation:hl}));return true;}catch{return false;}}
function lockAssassinFacing(target,ticks=20){try{const old=assassinFacingLocks.get(target.id);if(old)safe(()=>system.clearRun(old));const rot=target.getRotation();let t=0;const h=system.runInterval(()=>{try{t++;if(t>ticks||!target.isValid||health(target)<=0){system.clearRun(h);assassinFacingLocks.delete(target.id);return;}target.setRotation(rot);}catch{safe(()=>system.clearRun(h));assassinFacingLocks.delete(target.id);}},1);assassinFacingLocks.set(target.id,h);system.runTimeout(()=>{if(assassinFacingLocks.get(target.id)===h){safe(()=>system.clearRun(h));assassinFacingLocks.delete(target.id);}},ticks+2);}catch{}}
function assassinGasVisualAt(dim,c,phase=0){for(let i=0;i<18;i++){const u=(i+.5)/18,phi=Math.acos(1-2*u),theta=i*2.399963229728653+phase,r=4+(i%3)*4,id=i%3===0?"minecraft:basic_smoke_particle":"minecraft:villager_happy";particle(dim,id,{x:c.x+r*Math.sin(phi)*Math.cos(theta),y:c.y+1+r*Math.cos(phi),z:c.z+r*Math.sin(phi)*Math.sin(theta)});}for(let i=0;i<8;i++){const a=phase+i*Math.PI/4,r=11.5;particle(dim,"minecraft:villager_happy",{x:c.x+Math.cos(a)*r,y:c.y+.25+(i%3)*.7,z:c.z+Math.sin(a)*r});}}

function classItemId(id){return id?.startsWith("geumyi:")&&ALL_ITEMS.includes(id.substring(7));}
function setClassItemLocks(p,locked=true){try{const c=p.getComponent("minecraft:inventory")?.container;if(!c)return;for(let i=0;i<c.size;i++){const slot=c.getSlot(i);if(!slot?.hasItem?.()||!classItemId(slot.typeId))continue;slot.lockMode=locked?ItemLockMode.inventory:ItemLockMode.none;slot.keepOnDeath=locked;}}catch{}}
function clearItems(p){setClassItemLocks(p,false);for(const id of ALL_ITEMS)safe(()=>p.runCommand(`clear @s geumyi:${id}`));}
function giveItems(p,c){clearItems(p);if(c==="sword"){safe(()=>p.runCommand("give @s geumyi:warrior_sword 1"));for(const id of["sword_draw","sword_dash","sword_rise","sword_ult"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="archer"){for(const id of["archer_triple","archer_boom","archer_wire","archer_ult"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="mage"){safe(()=>p.runCommand("give @s geumyi:mage_staff 1"));for(const id of["mage_fireball","mage_shield","mage_vine","mage_thunder"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="cleric"){safe(()=>p.runCommand("give @s geumyi:cleric_bible 1"));for(const id of["cleric_recovery","cleric_shield","cleric_spear","cleric_prayer"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="berserker"){safe(()=>p.runCommand("give @s geumyi:berserker_axe 1"));for(const id of["berserker_rage","berserker_slam","berserker_tornado","berserker_ult"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="assassin"){safe(()=>p.runCommand("give @s geumyi:assassin_dagger 1"));for(const id of["assassin_prep","assassin_move","assassin_gas","assassin_ult"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`)); }else if(c==="fighter"){safe(()=>p.runCommand("give @s geumyi:fighter_gauntlet 1"));for(const id of["fighter_step","fighter_burst","fighter_flurry","fighter_limit"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`)); }else if(c==="hero"){safe(()=>p.runCommand("give @s geumyi:hero_sword 1"));for(const id of["hero_heart","hero_smite","hero_parry","hero_courage"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="reaper"){safe(()=>p.runCommand("give @s geumyi:reaper_scythe 1"));for(const id of["reaper_absorb","reaper_ambush","reaper_massacre","reaper_judgment"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}else if(c==="sheriff"){safe(()=>p.runCommand("give @s geumyi:sheriff_revolver 1"));for(const id of["sheriff_quickdraw","sheriff_rope","sheriff_enhance","sheriff_deadeye"])safe(()=>p.runCommand(`give @s geumyi:${id} 1`));}system.runTimeout(()=>setClassItemLocks(p,true),2);}
function resetFighterMovement(p){const mc=safe(()=>p.getComponent("minecraft:movement"));if(mc)safe(()=>mc.resetToDefaultValue());}
function onClassChanged(p,c){activeSkillCast.delete(p.id);skillUiUntil.delete(p.id);safe(()=>p.removeTag("geumyi_skill_ui_lock"));fighterFury.delete(p.id);fighterLimitUntil.delete(p.id);fighterCombo.delete(p.id);resetFighterMovement(p);assassinUltInvuln.delete(p.id);endHeroGuard(p);heroParryUntil.delete(p.id);heroSneakPrev.delete(p.id);fighterSneakPrev.delete(p.id);const hu=heroUltState.get(p.id);if(hu?.handle)safe(()=>system.clearRun(hu.handle));heroUltState.delete(p.id);reaperFlipState.delete(p.id);reaperJudgmentOverflow.delete(p.id);if(c==="none"){clearItems(p);safe(()=>p.removeEffect("speed"));safe(()=>p.removeEffect("health_boost"));safe(()=>p.removeEffect("invisibility"));assassinPrepStealthUntil.delete(p.id);fighterBonusHp.set(p.id,0);fighterBonusMaxSeen.set(p.id,0);return;}giveItems(p,c);if(c!=="archer")safe(()=>p.removeEffect("speed"));if(c!=="fighter")safe(()=>p.removeEffect("health_boost"));if(c!=="assassin"){safe(()=>p.removeEffect("invisibility"));assassinPrepStealthUntil.delete(p.id);}msg(p,"§7[장비] 전용 장비와 스킬 아이템 지급 완료");}
function fighterBonusMax(p){if(cls(p)!=="fighter")return 0;let n=0;for(const t of[10,30,50,70,100])if(level(p)>=t)n+=2;return n;}
function syncFighterBonus(p){const desired=fighterBonusMax(p),boostHp=desired-(desired%4),residual=desired-boostHp,prev=fighterBonusMaxSeen.get(p.id)??-1;if(cls(p)!=="fighter"){fighterBonusHp.set(p.id,0);fighterBonusMaxSeen.set(p.id,0);return;}if(boostHp>0){const amp=boostHp/4-1,eff=safe(()=>p.getEffect("health_boost"));if(prev!==desired||!eff||eff.amplifier!==amp||eff.duration<1200)safe(()=>p.addEffect("health_boost",72000,{amplifier:amp,showParticles:false}));}else if(prev!==desired)safe(()=>p.removeEffect("health_boost"));const hc=safe(()=>p.getComponent("minecraft:health")),cur=fighterBonusHp.get(p.id)??0;if(prev!==desired)fighterBonusHp.set(p.id,Math.min(residual,Math.max(0,cur+(residual-(prev<0?0:(prev%4))))));if(residual===0)fighterBonusHp.set(p.id,0);else if(hc&&(hc.currentValue??0)>=(hc.effectiveMax??20)-.01&&cur<residual)fighterBonusHp.set(p.id,residual);fighterBonusMaxSeen.set(p.id,desired);}
function fighterLimitActive(p){return cls(p)==="fighter"&&(fighterLimitUntil.get(p.id)??0)>now();}
function furyState(p){let st=fighterFury.get(p.id);if(!st){st={stacks:0,lastHit:now(),lastDecay:now()};fighterFury.set(p.id,st);}return st;}
function setFury(p,n,show=false){if(cls(p)!=="fighter")return;const st=furyState(p);st.stacks=Math.max(0,Math.min(FIGHTER_FURY_MAX,Math.floor(n)));if(st.stacks>0){st.lastHit=now();st.lastDecay=now();}applyFighterMovement(p);if(show)bar(p,`§6투지 §f${st.stacks}/${FIGHTER_FURY_MAX}${st.stacks===FIGHTER_FURY_MAX?" §c[철권 강화]":""}`,40);}
function addFury(p,n=1,show=true){const st=furyState(p);if(fighterLimitActive(p)){st.stacks=FIGHTER_FURY_MAX;st.lastHit=now();applyFighterMovement(p);return FIGHTER_FURY_MAX;}st.stacks=Math.min(FIGHTER_FURY_MAX,st.stacks+n);st.lastHit=now();st.lastDecay=now();applyFighterMovement(p);if(show)bar(p,`§6투지 §f${st.stacks}/${FIGHTER_FURY_MAX}${st.stacks===FIGHTER_FURY_MAX?" §c[철권 강화]":""}`,40);return st.stacks;}
function consumeFury(p){const st=furyState(p),n=st.stacks;if(!fighterLimitActive(p)){st.stacks=0;applyFighterMovement(p);}return n;}
function applyFighterMovement(p){const mc=safe(()=>p.getComponent("minecraft:movement"));if(!mc)return;const stacks=fighterLimitActive(p)?FIGHTER_FURY_MAX:(fighterFury.get(p.id)?.stacks??0),base=mc.defaultValue??0.1,target=base*(1+stacks*.02);safe(()=>mc.setCurrentValue(Math.min(mc.effectiveMax??target,target)));}
function updateFighterFury(p){if(cls(p)!=="fighter")return;const st=furyState(p);if(fighterLimitActive(p)){if(st.stacks!==FIGHTER_FURY_MAX){st.stacks=FIGHTER_FURY_MAX;applyFighterMovement(p);}return;}if(st.stacks>0&&now()-st.lastHit>=100&&now()-st.lastDecay>=20){st.stacks--;st.lastDecay=now();applyFighterMovement(p);}}
function fighterComboState(p){let st=fighterCombo.get(p.id);if(!st){st={burstInstantUntil:0,flurryBoostUntil:0};fighterCombo.set(p.id,st);}return st;}
function fighterComboWindow(p,normalTicks){return fighterLimitActive(p)?normalTicks*2:normalTicks;}
function armFighterBurstCombo(p){fighterComboState(p).burstInstantUntil=now()+fighterComboWindow(p,40);bar(p,"§6연계! §f붕권을 즉시 사용할 수 있습니다.",40);}
function armFighterFlurryCombo(p){fighterComboState(p).flurryBoostUntil=now()+fighterComboWindow(p,60);bar(p,"§6연계! §f난타의 탐색/추적 범위가 강화되었습니다.",40);}
