function mageTiming(p,id){const s=SKILLS[id],steps=Math.max(0,Math.floor((level(p)-s.level)/10));return{cast:Math.max(s.cast*.5,s.cast-steps*.1),cd:Math.max(s.cd*.5,s.cd-steps)};}
function validate(p,id){const s=SKILLS[id];if(!s)return false;if(cls(p)!==s.cls){bar(p,`§c${cname(s.cls)} 전용 스킬입니다.`);return false;}if(level(p)<s.level){bar(p,`§c${s.name}: Lv.${s.level}에 해금됩니다.`);return false;}if(skillBusy(p))return false;if(mageCasting.has(p.id)){bar(p,"§d마법 연산 중입니다.");return false;}const left=cdLeft(p,id);if(left>0){bar(p,`§c${s.name} 쿨타임 ${left}초`);return false;}return true;}
