function swordUltImpact(p){const l=p.location;particle(p.dimension,"minecraft:huge_explosion_emitter",{x:l.x,y:l.y+.8,z:l.z});for(let i=0;i<8;i++){const a=i*Math.PI/4,r=1.3+(i%2)*1.4;particle(p.dimension,"minecraft:critical_hit_emitter",{x:l.x+Math.cos(a)*r,y:l.y+.6+(i%3)*.32,z:l.z+Math.sin(a)*r});}for(const e of p.dimension.getEntities({location:l,maxDistance:5}))if(targetable(e))damage(e,20,p);sound(p,"random.sweep",.85,.9);system.runTimeout(()=>sound(p,"random.sweep",1.35,.8),2);system.runTimeout(()=>sound(p,"random.explode",1.15,.55),4);}
function castSwordUlt(p){if(!validate(p,"sword_ult"))return;startCd(p,"sword_ult",50);beginActiveSkill(p,"sword_ult");safe(()=>p.addTag("geumyi_sword_ult"));safe(()=>p.addEffect("invisibility",200,{amplifier:0,showParticles:false}));safe(()=>p.addEffect("speed",200,{amplifier:4,showParticles:false}));let sec=0;const h=system.runInterval(()=>{try{sec++;if(sec>10){safe(()=>p.removeTag("geumyi_sword_ult"));system.clearRun(h);endActiveSkill(p,"sword_ult");return;}swordUltImpact(p);}catch{system.clearRun(h);safe(()=>p.removeTag("geumyi_sword_ult"));endActiveSkill(p,"sword_ult");}},20);system.runTimeout(()=>{safe(()=>p.removeTag("geumyi_sword_ult"));endActiveSkill(p,"sword_ult");},205);bar(p,"§e풍흔만리! §f반지름 5칸 / 10초 / 매초 20데미지");}
function tripleVolley(p){const d=p.getViewDirection(),h=horizView(p),right={x:-h.z,z:h.x},base={x:p.location.x+d.x*.8,y:p.location.y+1.5+d.y*.8,z:p.location.z+d.z*.8};for(const side of[-1,0,1]){const back=side===0?0:.24,loc={x:base.x+right.x*.58*side-d.x*back,y:base.y,z:base.z+right.z*.58*side-d.z*back};spawnArrow(p,loc,{x:d.x*2,y:d.y*2,z:d.z*2},"geumyi_triple_arrow");}}
