function pullPlayer(p,to){let t=0;const h=system.runInterval(()=>{try{const dx=to.x-p.location.x,dy=to.y-(p.location.y+.6),dz=to.z-p.location.z,l=Math.hypot(dx,dy,dz);if(++t>20||l<.9){system.clearRun(h);return;}const dir={x:dx/l,z:dz/l};if(isWallAhead(p,dir)){system.clearRun(h);return;}p.clearVelocity();const s=Math.min(1.08,.60+l*.030);p.applyImpulse({x:dx/l*s,y:dy/l*s,z:dz/l*s});particle(p.dimension,"minecraft:basic_smoke_particle",{x:p.location.x,y:p.location.y+.8,z:p.location.z});}catch{system.clearRun(h);}},1);}
function castWire(p){if(!validate(p,"archer_wire"))return;startCd(p,"archer_wire",25);const d=p.getViewDirection(),a=spawnArrow(p,{x:p.location.x+d.x*.8,y:p.location.y+1.5+d.y*.8,z:p.location.z+d.z*.8},{x:d.x*3.25,y:d.y*3.25,z:d.z*3.25},"geumyi_wire_arrow");if(a)system.runTimeout(()=>safe(()=>a.remove()),30);sound(p,"random.bow",1.65);bar(p,"§b와이어 화살! §f쓕! §7(고속 당김)");}
