function spawnHoming(p,target,index=0){try{const ang=(index%12)*(Math.PI/6),r=.30+(index%3)*.08,spawn={x:p.location.x+Math.cos(ang)*r,y:p.location.y+1.45+((index%5)-2)*.055,z:p.location.z+Math.sin(ang)*r},tp=targetPoint(target),dx=tp.x-spawn.x,dy=tp.y-spawn.y,dz=tp.z-spawn.z,l=Math.hypot(dx,dy,dz)||1,a=spawnArrow(p,spawn,{x:dx/l*1.65,y:dy/l*1.65,z:dz/l*1.65},"geumyi_homing_arrow");if(a)homing.set(a.id,{a,target,owner:p,born:now()});}catch{}}
function startArrowOrbit(p,duration=410){const arrows=[];for(let i=0;i<14;i++){try{const a=p.dimension.spawnEntity("minecraft:arrow",{x:p.location.x,y:p.location.y+1.4,z:p.location.z});a.addTag("geumyi_skill_arrow");a.addTag("geumyi_orbit_arrow");arrows.push(a);}catch{}}let t=0;const h=system.runInterval(()=>{t+=2;if(t>duration){for(const a of arrows)safe(()=>a.remove());system.clearRun(h);return;}for(let i=0;i<arrows.length;i++){const a=arrows[i],ang=t*.055+i*(Math.PI*2/arrows.length),r=1.25+(i%2)*.35,y=p.location.y+.8+(i%3)*.42;safe(()=>a.teleport({x:p.location.x+Math.cos(ang)*r,y,z:p.location.z+Math.sin(ang)*r}));safe(()=>a.setRotation({x:0,y:ang*180/Math.PI+90}));}},2);}
