function castArcherUlt(p){if(!validate(p,"archer_ult"))return;const first=highestTarget(p);if(!first){bar(p,"§c주변에 공격할 대상이 없습니다.");return;}startCd(p,"archer_ult",50);archerUltState.set(p.id,{target:first});startArrowOrbit(p,410);safe(()=>p.onScreenDisplay.setTitle("§a§l백발백중",{subtitle:"§f최우선 표적 고정 · 100연사",fadeInDuration:2,stayDuration:18,fadeOutDuration:8}));const l=p.location;for(let i=0;i<16;i++){const a=i*Math.PI/8;particle(p.dimension,"minecraft:critical_hit_emitter",{x:l.x+Math.cos(a)*1.55,y:l.y+.65+(i%3)*.42,z:l.z+Math.sin(a)*1.55});}sound(p,"random.levelup",1.35,.9);system.runTimeout(()=>sound(p,"random.bow",.85,.8),4);system.runTimeout(()=>sound(p,"random.bow",1.15,.8),8);for(let i=0;i<100;i++)system.runTimeout(()=>{const st=archerUltState.get(p.id);if(!st)return;if(!validUltTarget(p,st.target))st.target=highestTarget(p);if(st.target)spawnHoming(p,st.target,i);if(i===99)system.runTimeout(()=>archerUltState.delete(p.id),80);},6+i*4);bar(p,"§a백발백중! §f최우선 표적부터 / 100발 / 1발 4데미지");}
