function beginMageCast(p,id,done){if(!validate(p,id))return;const t=mageTiming(p,id),ticks=Math.max(1,Math.round(t.cast*20));beginActiveSkill(p,id);mageCasting.set(p.id,{id,end:now()+ticks});safe(()=>p.addEffect("slowness",ticks+8,{amplifier:1,showParticles:false}));safe(()=>p.addEffect("weakness",ticks+8,{amplifier:0,showParticles:false}));msg(p,`§d[마법 연산 시작] §f${SKILLS[id].name} §7(${t.cast.toFixed(1)}초)`);let elapsed=0;const h=system.runInterval(()=>{try{elapsed+=5;const l=p.location;for(let i=0;i<3;i++)particle(p.dimension,"minecraft:enchanting_table_particle",{x:l.x+(Math.random()-.5)*2.2,y:l.y+.4+Math.random()*1.6,z:l.z+(Math.random()-.5)*2.2});if(elapsed%10===0)msg(p,GLYPHS[(elapsed/10)%GLYPHS.length|0]);if(elapsed>=ticks){system.clearRun(h);mageCasting.delete(p.id);endActiveSkill(p,id);safe(()=>p.removeEffect("slowness"));safe(()=>p.removeEffect("weakness"));startCd(p,id,t.cd);msg(p,"§d§l《 마법 연산 완료 》§r");sound(p,"random.levelup",1.4,.7);done();}}catch{mageCasting.delete(p.id);endActiveSkill(p,id);system.clearRun(h);}},5);}
