const UNDEAD=new Set(["minecraft:zombie","minecraft:husk","minecraft:drowned","minecraft:zombie_villager","minecraft:zombified_piglin","minecraft:skeleton","minecraft:stray","minecraft:wither_skeleton","minecraft:bogged","minecraft:phantom","minecraft:wither","minecraft:skeleton_horse","minecraft:zombie_horse"]);
function isUndead(e){return !!e&&UNDEAD.has(e.typeId);}
function healEntity(e,amount){const hc=safe(()=>e.getComponent("minecraft:health"));if(!hc)return false;const max=hc.effectiveMax??hc.defaultValue??20,cur=hc.currentValue??max;safe(()=>hc.setCurrentValue(Math.min(max,cur+amount)));return true;}
function nearbyPlayers(p,r){return world.getAllPlayers().filter(x=>x.dimension.id===p.dimension.id&&dist(x.location,p.location)<=r).sort((a,b)=>(a.id===p.id?-1:b.id===p.id?1:dist(a.location,p.location)-dist(b.location,p.location)));}
function holyBurst(dim,loc,r=1.2,count=10){for(let i=0;i<count;i++){const a=(Math.PI*2*i)/count,id=i%3===1?"minecraft:villager_happy":"minecraft:endrod";particle(dim,id,{x:loc.x+Math.cos(a)*r,y:loc.y+.65+(i%2)*.22,z:loc.z+Math.sin(a)*r});}}
function clericPulse(p,r,heal,mobDmg,ringCount){for(const ally of nearbyPlayers(p,r))healEntity(ally,heal);for(const e of (safe(()=>p.dimension.getEntities({location:p.location,maxDistance:r}))??[]))if(clericTarget(e))clericDamage(e,mobDmg,p);holyRing(p.dimension,p.location,r,ringCount,.32);}
function castBible(p){if(cls(p)!=="cleric"){bar(p,"§c성직자 전용 성경책입니다.");return;}const left=cdLeft(p,"cleric_bible");if(left>0){bar(p,`§e성경책 쿨타임 ${left}초`);return;}startCd(p,"cleric_bible",5);clericPulse(p,2.5,8,4,18);sound(p,"random.orb",1.35,.45);bar(p,"§f성경의 빛 §7- 반경 2.5칸 / 아군 8HP 회복 / 모든 몹 4데미지");}
