function releaseAssassinTarget(st){const t=st?.lockedTarget;if(!t)return;safe(()=>t.removeTag("geumyi_assassin_locked"));st.lockedTarget=undefined;st.anchor=undefined;st.rotation=undefined;}
function freezeAssassinTarget(st){const t=st?.lockedTarget;if(!t||!targetable(t))return;safe(()=>t.clearVelocity());if(st.anchor)safe(()=>t.teleport(st.anchor,{dimension:t.dimension}));if(st.rotation)safe(()=>t.setRotation(st.rotation));}
function lockAssassinTarget(st,t){releaseAssassinTarget(st);st.lockedTarget=t;st.anchor={x:t.location.x,y:t.location.y,z:t.location.z};st.rotation=safe(()=>t.getRotation());safe(()=>t.addTag("geumyi_assassin_locked"));freezeAssassinTarget(st);}
