function castAssassinUlt(p){if(!validate(p,"assassin_ult"))return;const first=strongestTarget(p,24);if(!first){bar(p,"§c주변에 암살할 대상이 없습니다.");return;}startCd(p,"assassin_ult",50);beginActiveSkill(p,"assassin_ult");assassinUltInvuln.add(p.id);const st={remaining:400,visited:new Set(),target:first,hops:0,handle:undefined,lockedTarget:undefined,anchor:undefined,rotation:undefined};const hop=()=>{if(!st.target||!targetable(st.target)||health(st.target)<=0){releaseAssassinTarget(st);if(st.hops>=5||st.remaining<=0){finishAssassinUlt(p);return false;}st.target=strongestTarget(p,24,st.visited);if(!st.target){finishAssassinUlt(p);return false;}}if(!st.visited.has(st.target.id)){st.hops++;st.visited.add(st.target.id);teleportBehind(p,st.target);assassinWhoosh(p);particle(p.dimension,"minecraft:critical_hit_emitter",p.location);lockAssassinTarget(st,st.target);}keepAssassinBehind(p,st.target);return true;};assassinUltState.set(p.id,st);if(!hop())return;st.handle=system.runInterval(()=>{try{if(st.remaining<=0||st.hops>5){finishAssassinUlt(p);return;}if(!st.target||!targetable(st.target)||health(st.target)<=0){st.target=undefined;if(!hop())return;}if(!st.target)return;freezeAssassinTarget(st);keepAssassinBehind(p,st.target);const hp=Math.max(0,health(st.target)),hit=Math.min(20,st.remaining,hp>0?hp:20);if(hit<=0){releaseAssassinTarget(st);st.target=undefined;return;}const impact=targetPoint(st.target),applied=damage(st.target,hit,p);if(!applied)return;st.remaining=Math.max(0,st.remaining-hit);system.run(()=>{freezeAssassinTarget(st);if(st.target)keepAssassinBehind(p,st.target);});particle(p.dimension,"minecraft:critical_hit_emitter",impact);sound(p,"random.sweep",1.4,.5);if(health(st.target)<=0){releaseAssassinTarget(st);st.target=undefined;}if(st.remaining<=0)finishAssassinUlt(p);}catch{finishAssassinUlt(p);}},10);bar(p,"§8단체 암살! §f총 피해 400 / 최대 5대상 / 시전 중 피해·넉백 면역");}

// Hero / 용사
function heroValor(p){const n=Number(safe(()=>p.getDynamicProperty(HERO_VALOR_KEY))??0);return Number.isFinite(n)?Math.max(0,Math.min(HERO_VALOR_MAX,Math.floor(n))):0;}
function setHeroValor(p,n,show=true){const v=Math.max(0,Math.min(HERO_VALOR_MAX,Math.floor(n)));safe(()=>p.setDynamicProperty(HERO_VALOR_KEY,v));if(show)bar(p,`§b용맹 §f${v}/${HERO_VALOR_MAX}`,40);return v;}
function addHeroValor(p,n){return setHeroValor(p,heroValor(p)+n,true);}
function heroFrontSource(p,atk,proj,deg=140){try{const v=horizView(p),cs=Math.cos((deg/2)*Math.PI/180);let dx=0,dz=0;if(atk&&atk.isValid!==false){dx=atk.location.x-p.location.x;dz=atk.location.z-p.location.z;}else if(proj){const pv=proj.getVelocity();dx=-pv.x;dz=-pv.z;}const l=Math.hypot(dx,dz)||1;return (dx/l)*v.x+(dz/l)*v.z>=cs;}catch{return true;}}
function spawnHeroGuardVisual(p){try{const old=heroGuardVisual.get(p.id);if(old&&old.isValid!==false)safe(()=>old.remove());const v=horizView(p),loc={x:p.location.x+v.x*.62,y:p.location.y-.10,z:p.location.z+v.z*.62};const stand=p.dimension.spawnEntity("minecraft:armor_stand",loc);safe(()=>stand.addTag("geumyi_hero_guard_visual"));safe(()=>stand.addEffect("invisibility",140,{amplifier:0,showParticles:false}));const eq=safe(()=>stand.getComponent("minecraft:equippable"));if(eq){const shield=new ItemStack("minecraft:shield",1);shield.nameTag="§b용사의 방패";safe(()=>eq.setEquipment(EquipmentSlot.Mainhand,shield));}const rot=safe(()=>p.getRotation(),{x:0,y:0});safe(()=>stand.setRotation({x:0,y:rot.y}));heroGuardVisual.set(p.id,stand);return stand;}catch{return undefined;}}
function updateHeroGuardVisual(p){try{let stand=heroGuardVisual.get(p.id);if(!stand||stand.isValid===false)stand=spawnHeroGuardVisual(p);if(!stand)return;const v=horizView(p),rot=safe(()=>p.getRotation(),{x:0,y:0});safe(()=>stand.teleport({x:p.location.x+v.x*.62,y:p.location.y-.10,z:p.location.z+v.z*.62},{dimension:p.dimension,rotation:{x:0,y:rot.y},keepVelocity:false,checkForBlocks:false}));}catch{}}
function endHeroGuard(p){heroGuardUntil.delete(p.id);const stand=heroGuardVisual.get(p.id);if(stand)safe(()=>stand.remove());heroGuardVisual.delete(p.id);}
function reflectHeroProjectile(p,proj,atk){try{const origin=p.getHeadLocation(),target=atk&&atk.isValid!==false?targetPoint(atk):null;let d;if(target){const dx=target.x-origin.x,dy=target.y-origin.y,dz=target.z-origin.z,l=Math.hypot(dx,dy,dz)||1;d={x:dx/l,y:dy/l,z:dz/l};}else{const v=proj.getVelocity(),l=Math.hypot(v.x,v.y,v.z)||1;d={x:-v.x/l,y:-v.y/l,z:-v.z/l};}if(proj.typeId==="minecraft:arrow"){const a=p.dimension.spawnEntity("minecraft:arrow",{x:origin.x+d.x*.8,y:origin.y-.1+d.y*.8,z:origin.z+d.z*.8});a.addTag("geumyi_hero_reflected");const pc=a.getComponent("minecraft:projectile");if(pc){pc.owner=p;pc.shoot({x:d.x*1.8,y:d.y*1.8,z:d.z*1.8});}safe(()=>proj.remove());}else{const pc=proj.getComponent("minecraft:projectile");if(pc){pc.owner=p;safe(()=>proj.teleport({x:origin.x+d.x*.8,y:origin.y-.1+d.y*.8,z:origin.z+d.z*.8},{dimension:p.dimension}));pc.shoot({x:d.x*1.55,y:d.y*1.55,z:d.z*1.55});}}sound(p,"random.anvil_land",1.5,.35);particle(p.dimension,"minecraft:trial_spawner_detection_ominous",{x:origin.x+d.x*.7,y:origin.y-.2,z:origin.z+d.z*.7});}catch{}}
function heroSlashFx(p,loc,strong=false){particle(p.dimension,"minecraft:critical_hit_emitter",loc);particle(p.dimension,"minecraft:evocation_fang_particle",{x:loc.x,y:loc.y-.2,z:loc.z});if(strong)system.runTimeout(()=>particle(p.dimension,"minecraft:critical_hit_emitter",{x:loc.x+.22,y:loc.y+.15,z:loc.z-.22}),1);sound(p,"random.sweep",strong?.78:1.05,strong?.9:.65);}
function heroAreaSlashFx(p,r=3){try{const l=p.location,phase=(now()%40)*.14;for(let i=0;i<16;i++){const a=phase+i*Math.PI*2/16,rr=r*(.58+(i%2)*.38),loc={x:l.x+Math.cos(a)*rr,y:l.y+.45+(i%4)*.18,z:l.z+Math.sin(a)*rr};particle(p.dimension,i%2===0?"minecraft:critical_hit_emitter":"minecraft:evocation_fang_particle",loc);}sound(p,"random.sweep",.88,.9);system.runTimeout(()=>sound(p,"random.sweep",1.22,.55),2);}catch{}}
function heroAreaSlash(p,r=3,dmg=20){let hits=0;for(const e of p.dimension.getEntities({location:p.location,maxDistance:r+.15})){if(!targetable(e))continue;if(damage(e,dmg,p))hits++;}heroAreaSlashFx(p,r);return hits;}
function heroConeSlashFx(p,r=5,deg=160){try{const l=p.location,d=horizView(p),base=Math.atan2(d.z,d.x),half=deg*Math.PI/360,points=19;for(let i=0;i<points;i++){const q=i/(points-1),a=base-half+q*half*2,rr=r*(.72+.24*Math.sin(q*Math.PI)),loc={x:l.x+Math.cos(a)*rr,y:l.y+.55+Math.sin(q*Math.PI)*.55,z:l.z+Math.sin(a)*rr};particle(p.dimension,i%2===0?"minecraft:critical_hit_emitter":"minecraft:evocation_fang_particle",loc);}sound(p,"random.sweep",.92,.72);system.runTimeout(()=>sound(p,"random.sweep",1.18,.34),2);}catch{}}
function heroConeSlash(p,r=5,deg=160,dmg=20){let hits=0;for(const e of coneTargets(p,r,deg)){if(damage(e,dmg,p))hits++;}heroConeSlashFx(p,r,deg);return hits;}
function pushFromEntity(source,target,power=.8,y=.16){try{const dx=target.location.x-source.location.x,dz=target.location.z-source.location.z,l=Math.hypot(dx,dz)||1;target.clearVelocity();target.applyImpulse({x:dx/l*power,y,z:dz/l*power});}catch{}}
function castHeroSword(p){if(cls(p)!=="hero"){bar(p,"§c용사 전용검입니다.");return;}if(skillBusy(p))return;const left=cdLeft(p,"hero_sword");if(left>0){bar(p,`§b용사의 검 방어 쿨타임 ${left}초`);return;}startCd(p,"hero_sword",20);endHeroGuard(p);heroGuardUntil.set(p.id,now()+120);spawnHeroGuardVisual(p);safe(()=>p.addEffect("slowness",120,{amplifier:0,showParticles:false}));const h=system.runInterval(()=>{try{if((heroGuardUntil.get(p.id)??0)<=now()||cls(p)!=="hero"){system.clearRun(h);endHeroGuard(p);return;}updateHeroGuardVisual(p);}catch{system.clearRun(h);endHeroGuard(p);}},2);system.runTimeout(()=>{safe(()=>system.clearRun(h));if((heroGuardUntil.get(p.id)??0)<=now())endHeroGuard(p);},122);sound(p,"random.anvil_use",1.25,.45);bar(p,"§b용사의 검 방어! §f6초 / 방패 모션 / 원거리 반사 / 근거리 피해 차단·밀치기");}
function heroFanfare(p){sound(p,"note.harp",.72,.75);system.runTimeout(()=>sound(p,"note.harp",.82,.75),3);system.runTimeout(()=>sound(p,"note.harp",1.02,.82),6);system.runTimeout(()=>sound(p,"note.harp",1.28,.95),9);system.runTimeout(()=>sound(p,"raid.horn",1.15,.28),2);} function castHeroHeart(p){if(!validate(p,"hero_heart"))return;startCd(p,"hero_heart",40);addHeroValor(p,3);for(const a of world.getAllPlayers()){if(a.dimension.id!==p.dimension.id||dist(a.location,p.location)>6)continue;safe(()=>a.addEffect("speed",400,{amplifier:0,showParticles:false}));safe(()=>a.addEffect("strength",400,{amplifier:0,showParticles:false}));trialBarRise(a,false);}heroFanfare(p);bar(p,"§6용맹한 전사의 마음! §f반경 6칸 아군 힘 I·신속 I 20초 / 용맹 +3");}
function castHeroSmite(p){if(!validate(p,"hero_smite"))return;startCd(p,"hero_smite",40);const ts=coneTargets(p,4.2,115);let hits=0;for(const e of ts){if(damage(e,30,p))hits++;pushAwayFrom(p,e,1.05,.22);heroSlashFx(p,targetPoint(e),true);}if(hits>0)addHeroValor(p,hits*3);const d=horizView(p);heroSlashFx(p,{x:p.location.x+d.x*1.8,y:p.location.y+.9,z:p.location.z+d.z*1.8},true);bar(p,`§c강타! §f${hits}명 적중 / 30데미지 + 넉백 / 용맹 +${hits*3}`);}
