function finishHeroCourage(p){const st=heroUltState.get(p.id);if(st?.handle)safe(()=>system.clearRun(st.handle));heroUltState.delete(p.id);bar(p,"§6용맹한 기사의 용기 종료");}
function castHeroCourage(p){if(!validate(p,"hero_courage"))return;startCd(p,"hero_courage",65);const stacks=heroValor(p);setHeroValor(p,0,false);const str=stacks>=12?1:0,spd=stacks>=6?1:0,res=stacks>=18?0:-1;safe(()=>p.addEffect("strength",600,{amplifier:str,showParticles:false}));safe(()=>p.addEffect("speed",600,{amplifier:spd,showParticles:false}));if(res>=0)safe(()=>p.addEffect("resistance",600,{amplifier:res,showParticles:false}));if(stacks>=24)safe(()=>p.addEffect("instant_health",1,{amplifier:1,showParticles:false}));if(stacks>=30)safe(()=>p.addEffect("regeneration",600,{amplifier:0,showParticles:false}));let ticks=0;const h=system.runInterval(()=>{try{ticks+=2;if(ticks>600||cls(p)!=="hero"){finishHeroCourage(p);return;}const t=nearestTarget(p,8);if(!t)return;const d=dist(p.location,t.location);if(d>5&&d<=8){const dx=t.location.x-p.location.x,dz=t.location.z-p.location.z,l=Math.hypot(dx,dz)||1;p.clearVelocity();p.applyImpulse({x:dx/l*.38,y:.02,z:dz/l*.38});}if(ticks%20===0&&coneTargets(p,5,160).length>0)heroConeSlash(p,5,160,20);}catch{finishHeroCourage(p);}},2);heroUltState.set(p.id,{handle:h,stacks});for(let i=0;i<12;i++){const a=i*Math.PI/6;particle(p.dimension,i%2?"minecraft:critical_hit_emitter":"minecraft:evocation_fang_particle",{x:p.location.x+Math.cos(a)*1.2,y:p.location.y+.3+(i%3)*.35,z:p.location.z+Math.sin(a)*1.2});}areaSound(p,"horn.call.1",1.0,1.0,96,p.location);bar(p,`§6용맹한 기사의 용기! §f용맹 ${stacks}/${HERO_VALOR_MAX} 사용 / 30초 · 전방 160° · 사거리 5칸 반자동 검격`);}


// Reaper / 사신
const REAPER_RED_PARTICLE="minecraft:redstone_wire_dust_particle";
const REAPER_DARK_PARTICLE="minecraft:basic_smoke_particle";
function reaperSoul(p){const n=Number(safe(()=>p.getDynamicProperty(REAPER_SOUL_KEY))??0);return Number.isFinite(n)?Math.max(0,Math.min(REAPER_SOUL_MAX,Math.floor(n))):0;}
function setReaperSoul(p,n,announce=true){const v=Math.max(0,Math.min(REAPER_SOUL_MAX,Math.floor(n)));safe(()=>p.setDynamicProperty(REAPER_SOUL_KEY,v));if(announce)msg(p,`§8[영혼] §f영혼: §c${v}§f/${REAPER_SOUL_MAX}`);return v;}
function addReaperSoul(p,n=1,announce=true){return setReaperSoul(p,reaperSoul(p)+n,announce);}
function spendReaperSoul(p,n){const have=reaperSoul(p);if(have<n){bar(p,`§c영혼이 부족합니다. §7(${n} 필요 / 보유 ${have})`);return false;}setReaperSoul(p,have-n,true);return true;}
function isSoulEntity(e){return !!e&&e.typeId==="geumyi:reaper_soul";}
function reaperSoulBubbleFx(dim,loc,phase=0){const t=(now()+phase)*.42,ox=Math.sin(t)*.065,oz=Math.cos(t*.83)*.055;particle(dim,REAPER_DARK_PARTICLE,{x:loc.x+ox,y:loc.y+.28,z:loc.z+oz});system.runTimeout(()=>particle(dim,REAPER_DARK_PARTICLE,{x:loc.x-ox*.65,y:loc.y+.43,z:loc.z-oz*.45}),1);system.runTimeout(()=>particle(dim,REAPER_DARK_PARTICLE,{x:loc.x+ox*.35,y:loc.y+.58,z:loc.z+oz*.55}),2);}
function reaperSoulPullFx(p,from){const to={x:p.location.x,y:p.location.y+1.0,z:p.location.z};for(let i=0;i<5;i++)system.runTimeout(()=>{const q=(i+1)/5;particle(p.dimension,REAPER_DARK_PARTICLE,{x:from.x+(to.x-from.x)*q,y:from.y+(to.y-from.y)*q+.12*Math.sin(q*Math.PI),z:from.z+(to.z-from.z)*q});},i);}
function spawnReaperSoul(dim,loc){try{const e=dim.spawnEntity("geumyi:reaper_soul",{x:loc.x,y:loc.y+.18,z:loc.z});reaperSoulBubbleFx(dim,{x:loc.x,y:loc.y+.18,z:loc.z});return e;}catch{return undefined;}}
function absorbSoulEntity(p,e){try{if(cls(p)!=="reaper"){bar(p,"§c사신만 영혼을 흡수할 수 있습니다.");return false;}if(reaperSoul(p)>=REAPER_SOUL_MAX){bar(p,"§c영혼 저장량이 최대입니다.");return false;}if(!e||e.isValid===false||!isSoulEntity(e))return false;const l={...e.location};reaperSoulPullFx(p,{x:l.x,y:l.y+.35,z:l.z});safe(()=>e.remove());addReaperSoul(p,1,true);particle(p.dimension,REAPER_DARK_PARTICLE,{x:p.location.x,y:p.location.y+1.0,z:p.location.z});sound(p,"random.orb",.62,.35);return true;}catch{return false;}}
function absorbNearbySouls(p,r=10){let n=0;for(const e of (safe(()=>p.dimension.getEntities({type:"geumyi:reaper_soul",location:p.location,maxDistance:r}))??[])){if(reaperSoul(p)>=REAPER_SOUL_MAX)break;if(absorbSoulEntity(p,e))n++;}return n;}
function useReaperSoul100(p){if(cls(p)!=="reaper"){bar(p,"§c사신만 사용할 수 있습니다.");return;}setReaperSoul(p,REAPER_SOUL_MAX,true);safe(()=>p.runCommand("clear @s geumyi:reaper_soul_100 0 1"));sound(p,"random.orb",.72,.8);system.runTimeout(()=>sound(p,"random.orb",1.05,.55),2);bar(p,"§8영혼 결정 사용! §f영혼을 100/100으로 채웠습니다.");}
function reaperHeal(p,amount,overflow=false){if(!Number.isFinite(amount)||amount<=0)return 0;const hc=safe(()=>p.getComponent("minecraft:health"));if(!hc)return 0;const max=hc.effectiveMax??hc.defaultValue??20,cur=hc.currentValue??max,need=Math.max(0,max-cur),heal=Math.min(need,amount);if(heal>0)safe(()=>hc.setCurrentValue(Math.min(max,cur+heal)));const extra=Math.max(0,amount-heal);if(overflow&&extra>0){const prev=reaperJudgmentOverflow.get(p.id)?.amount??0,total=Math.min(20,prev+extra);reaperJudgmentOverflow.set(p.id,{amount:total,until:now()+600});const amp=Math.max(0,Math.min(4,Math.ceil(total/4)-1));safe(()=>p.addEffect("absorption",600,{amplifier:amp,showParticles:false}));}return heal;}
function reaperDamage(e,n,p,leech=0,overflow=false){if(!targetable(e)||!Number.isFinite(n)||n<=0)return 0;const before=Math.max(0,health(e));reaperSkillDamageBypass.set(p.id,now()+2);const ok=damage(e,n,p);if(!ok)return 0;if(leech>0)system.run(()=>{try{const after=Math.max(0,health(e));const actual=Math.max(0,Math.min(n,before-after));if(actual>0)reaperHeal(p,actual*leech,overflow);}catch{}});return Math.min(n,before>0?before:n);}
