function castReaperAmbush(p){if(!validate(p,"reaper_ambush"))return;if(!spendReaperSoul(p,5))return;startCd(p,"reaper_ambush",20);beginActiveSkill(p,"reaper_ambush");const dir=horizView(p),hit=new Set(),start={...p.location},steps=10,stepDist=.8;reaperFlipState.set(p.id,now()+70);let step=0;const h=system.runInterval(()=>{try{if(cls(p)!=="reaper"||step>=steps||isWallAhead(p,dir)){system.clearRun(h);endActiveSkill(p,"reaper_ambush");bar(p,`§c사신의 복병 종료 §7/ 이동 ${Math.min(8,step*stepDist).toFixed(1)}칸 / 적중 ${hit.size}명`);return;}step++;const travel=step*stepDist,dest={x:start.x+dir.x*travel,y:start.y,z:start.z+dir.z*travel};safe(()=>p.teleport(dest,{dimension:p.dimension,checkForBlocks:false,facingLocation:{x:dest.x+dir.x*4,y:dest.y+1,z:dest.z+dir.z*4}}));const phase=step*.95;for(let j=0;j<5;j++){const a=phase+j*Math.PI*2/5,r=.65+j*.10;particle(p.dimension,j%2?REAPER_RED_PARTICLE:REAPER_DARK_PARTICLE,{x:p.location.x+Math.cos(a)*r,y:p.location.y+.45+(j%3)*.32,z:p.location.z+Math.sin(a)*r});}for(const e of p.dimension.getEntities({location:p.location,maxDistance:2.35})){if(!targetable(e)||hit.has(e.id))continue;hit.add(e.id);const dealt=reaperDamage(e,25,p,.30,false);if(dealt>0)reaperSlashAt(p,targetPoint(e),true);}if(step===steps){system.clearRun(h);endActiveSkill(p,"reaper_ambush");bar(p,`§c사신의 복병 종료 §7/ 이동 8칸 / 적중 ${hit.size}명`);}}catch{safe(()=>system.clearRun(h));endActiveSkill(p,"reaper_ambush");}},1);sound(p,"mob.enderdragon.flap",1.58,.42);system.runTimeout(()=>sound(p,"random.sweep",.68,.78),4);bar(p,"§c사신의 복병! §f최대 8칸 돌진 / 궤도 적 25데미지 / 흡혈 30%");}
function massacreAimTarget(p,maxRange=14){const d=horizView(p),list=coneTargets(p,maxRange,70);list.sort((a,b)=>{const ax=a.location.x-p.location.x,az=a.location.z-p.location.z,al=Math.hypot(ax,az)||1,bx=b.location.x-p.location.x,bz=b.location.z-p.location.z,bl=Math.hypot(bx,bz)||1;const ad=(ax/al)*d.x+(az/al)*d.z,bd=(bx/bl)*d.x+(bz/bl)*d.z;return (bd-ad)*8+(al-bl)*.08;});return list[0];}
function massacreTargetsAt(p,center,r=9){const out=[];for(const e of (safe(()=>p.dimension.getEntities({location:center,maxDistance:r+1.2}))??[])){if(!targetable(e))continue;const dx=e.location.x-center.x,dz=e.location.z-center.z,dy=Math.abs(e.location.y-center.y);if(Math.hypot(dx,dz)<=r+.35&&dy<=4.75)out.push(e);}return out;}
function massacreRingFx(p,center,phase,r=9,tick=0){
  // v1.2.4: 단순 원 테두리 대신, 시전 초기에 보이던 '사선 참격'이 낫과 함께 4바퀴 내내 회전한다.
  // 중심 -> 바깥날 방향으로 올라가는 사선 2겹 + 짧은 잔상을 사용해 모바일에서도 과도한 파티클을 피한다.
  for(let trail=0;trail<2;trail++){
    const a=phase-trail*.085;
    for(let i=0;i<=12;i++){
      const q=i/12,rr=.75+q*(r-.35),lift=.18+q*1.18+Math.sin(q*Math.PI)*.28;
      const loc={x:center.x+Math.cos(a)*rr,y:center.y+lift,z:center.z+Math.sin(a)*rr};
      particle(p.dimension,REAPER_RED_PARTICLE,loc);
      if((i+trail)%5===0)particle(p.dimension,REAPER_DARK_PARTICLE,{x:loc.x-Math.sin(a)*.10,y:loc.y+.04,z:loc.z+Math.cos(a)*.10});
    }
  }
  // 낫날 끝의 궤적을 짧게 남긴다.
  for(let j=0;j<5;j++){
    const a=phase-j*.07;
    particle(p.dimension,REAPER_RED_PARTICLE,{x:center.x+Math.cos(a)*r,y:center.y+.22+j*.035,z:center.z+Math.sin(a)*r});
  }
  // 공격 범위(반지름 9)의 둘레를 붉은 파티클로 표시한다.
  // 매 4틱마다 18점을 찍어 원형 경계는 유지하면서 과도한 파티클 증가는 줄인다.
  if(tick%4===0){
    const edgeOffset=(tick/4%2)*Math.PI/18;
    for(let i=0;i<18;i++){
      const a=edgeOffset+i*Math.PI*2/18;
      particle(p.dimension,REAPER_RED_PARTICLE,{x:center.x+Math.cos(a)*r,y:center.y+.18,z:center.z+Math.sin(a)*r});
    }
  }
}
function startReaperMassacreOrbit(p,center,travelVisual){
  beginActiveSkill(p,"reaper_massacre");
  // 기존 v1.4.7 회전 방식/궤도/외형은 그대로 유지한다. 이동용 낫만 제거하고 수평 회전 전용 낫을 사용한다.
  safe(()=>travelVisual?.remove());
  let visual=spawnReaperMassacreOrbitVisual(p,{x:center.x,y:center.y+.92,z:center.z});
  const turnTicks=20,totalTurns=4,totalTicks=turnTicks*totalTurns,unique=new Set();
  let t=0,lastTurn=0;
  const h=system.runInterval(()=>{try{
    t+=2;
    if(cls(p)!=="reaper"||t>totalTicks){safe(()=>visual?.remove());system.clearRun(h);endActiveSkill(p,"reaper_massacre");return;}
    // 회전용 낫이 외부 피해/비정상 소멸로 사라져도 플레이어 타이머는 중단하지 않고 같은 회전 낫을 즉시 복구한다.
    if(!visual?.isValid)visual=spawnReaperMassacreOrbitVisual(p,{x:center.x,y:center.y+.92,z:center.z});
    if(visual)safe(()=>visual.teleport({x:center.x,y:center.y+.92,z:center.z},{dimension:p.dimension,checkForBlocks:false}));
    const phase=(t/turnTicks)*Math.PI*2;
    massacreRingFx(p,center,phase,9,t);
    const completed=Math.min(totalTurns,Math.floor(t/turnTicks));
    if(completed>lastTurn){
      lastTurn=completed;let hitThisTurn=0;
      for(const e of massacreTargetsAt(p,center,9)){
        const dealt=reaperDamage(e,55,p,.40,false);
        if(dealt>0){hitThisTurn++;unique.add(e.id);}
      }
      particle(p.dimension,"minecraft:critical_hit_emitter",{x:center.x,y:center.y+1.0,z:center.z});
      areaSound(p,"random.sweep",.64+completed*.08,.55,32,center);
      bar(p,`§4사신의 학살 §f${completed}/${totalTurns}바퀴 · 이번 타격 ${hitThisTurn}명 · 55데미지`,24);
    }
    if(t>=totalTicks){
      safe(()=>visual?.remove());system.clearRun(h);endActiveSkill(p,"reaper_massacre");
      bar(p,`§4사신의 학살 종료 §7/ 반지름 9칸 / 4바퀴 / 대상당 최대 220 / 적중 ${unique.size}명`);
    }
  }catch{safe(()=>visual?.remove());safe(()=>system.clearRun(h));endActiveSkill(p,"reaper_massacre");}},2);
}
