world.beforeEvents.entityHurt.subscribe(ev=>{try{
 const hurt=ev.hurtEntity,proj=ev.damageSource.damagingProjectile,atk=ev.damageSource.damagingEntity;
 if(hurt?.typeId==="geumyi:reaper_soul"||hurt?.typeId==="geumyi:reaper_scythe_projectile"||hurt?.typeId==="geumyi:reaper_massacre_orbit"){ev.cancel=true;return;}
 if(hurt.typeId==="minecraft:player"&&assassinUltInvuln.has(hurt.id)){ev.cancel=true;safe(()=>hurt.clearVelocity());return;}
 if(hurt.typeId==="minecraft:player"&&cls(hurt)==="hero"){
   const guard=(heroGuardUntil.get(hurt.id)??0)>now(),parry=(heroParryUntil.get(hurt.id)??0)>now();
   if(proj&&(parry||(guard&&heroFrontSource(hurt,atk,proj)))){ev.cancel=true;system.run(()=>{reflectHeroProjectile(hurt,proj,atk);if(guard)addHeroValor(hurt,2);});return;}
   if(!proj&&atk&&atk.id!==hurt.id){
     if(guard&&heroFrontSource(hurt,atk,undefined)){ev.cancel=true;system.run(()=>{addHeroValor(hurt,1);pushFromEntity(hurt,atk,.95,.20);particle(hurt.dimension,"minecraft:trial_spawner_detection_ominous",targetPoint(atk));});return;}
     if(parry&&Math.random()<.75){ev.cancel=true;system.run(()=>{if(targetable(atk))damage(atk,45,hurt);heroSlashFx(hurt,targetPoint(atk),true);pushFromEntity(hurt,atk,.65,.16);});return;}
   }
 }
 if(hurt.typeId==="minecraft:player"&&assassinMoveInvuln.has(hurt.id)){ev.cancel=true;return;}
 if(hurt.typeId==="minecraft:player"&&berserkerSlamFallGuard.has(hurt.id)&&(ev.damageSource.cause===EntityDamageCause.fall||ev.damageSource.cause==="fall")){ev.cancel=true;return;}
 if(hurt.typeId==="minecraft:player"&&cls(hurt)==="reaper"&&(reaperFlipState.get(hurt.id)??0)>now()&&(ev.damageSource.cause===EntityDamageCause.fall||ev.damageSource.cause==="fall")){ev.cancel=true;return;}
 if(proj?.hasTag("geumyi_skill_arrow")){ev.cancel=true;return;}
 if(atk?.hasTag("geumyi_stunned")||atk?.hasTag("geumyi_paralyzed")||atk?.hasTag("geumyi_cleric_stunned")||atk?.hasTag("geumyi_berserker_locked")||atk?.hasTag("geumyi_assassin_locked")||atk?.hasTag("geumyi_fighter_locked")){ev.cancel=true;return;}
 if(hurt.typeId==="minecraft:player"&&hurt.hasTag("geumyi_sword_ult")){ev.cancel=true;return;}
 if(hurt.typeId==="minecraft:player"&&cls(hurt)==="assassin"&&assassinStealthed(hurt)&&atk&&atk.typeId!=="minecraft:player"){ev.cancel=true;return;}
 if(hurt.typeId==="minecraft:player"&&fighterLimitActive(hurt)&&!fighterDefenseBypass.has(hurt.id)){
   const reduced=ev.damage*.70,cause=ev.damageSource.cause,damager=atk;ev.cancel=true;
   system.run(()=>{fighterDefenseBypass.add(hurt.id);safe(()=>hurt.applyDamage(reduced,damager?{cause,damagingEntity:damager}:{cause}));system.runTimeout(()=>fighterDefenseBypass.delete(hurt.id),2);});return;
 }
 if(proj?.typeId==="minecraft:arrow"&&!proj.hasTag("geumyi_skill_arrow")&&atk?.typeId==="minecraft:player"&&(explosiveUntil.get(atk.id)??0)>now()){ev.cancel=true;return;}
 if(atk?.typeId==="minecraft:player"){
   if(cls(atk)==="assassin"&&(assassinPrepStealthUntil.get(atk.id)??0)>now()&&!assassinDamageBypass.has(atk.id)){assassinPrepStealthUntil.delete(atk.id);safe(()=>atk.removeEffect("invisibility"));}
   const held=safe(()=>atk.getComponent("minecraft:equippable")?.getEquipment(EquipmentSlot.Mainhand));
   if(held?.typeId==="geumyi:warrior_sword"&&cls(atk)!=="sword"){ev.cancel=true;system.run(()=>bar(atk,"§c검사 전용검입니다."));return;}
   if(held?.typeId==="geumyi:hero_sword"){if(cls(atk)!=="hero"){ev.cancel=true;system.run(()=>bar(atk,"§c용사 전용검입니다."));return;}addHeroValor(atk,1);} 
   if(held?.typeId==="geumyi:reaper_scythe"&&cls(atk)!=="reaper"){ev.cancel=true;system.run(()=>bar(atk,"§c사신 전용 대낫입니다."));return;}
   if(held?.typeId==="geumyi:berserker_axe"){if(cls(atk)!=="berserker"){ev.cancel=true;system.run(()=>bar(atk,"§c광전사 전용 손도끼입니다."));return;}if(hurt.typeId==="minecraft:player")system.run(()=>safe(()=>hurt.startItemCooldown("shield",100)));}
   if(held?.typeId==="geumyi:assassin_dagger"){if(cls(atk)!=="assassin"){ev.cancel=true;system.run(()=>bar(atk,"§c암살자 전용 단검입니다."));return;}if(!assassinDamageBypass.has(atk.id)&&isBehindTarget(atk,hurt)){const amount=ev.damage*2,cause=ev.damageSource.cause,impact={x:hurt.location.x,y:hurt.location.y+1,z:hurt.location.z};ev.cancel=true;system.run(()=>{assassinDamageBypass.add(atk.id);safe(()=>hurt.applyDamage(amount,{cause,damagingEntity:atk}));particle(atk.dimension,"minecraft:critical_hit_emitter",impact);sound(atk,"random.sweep",1.65,.55);bar(atk,"§8배후 공격! §f피해 2배");system.runTimeout(()=>assassinDamageBypass.delete(atk.id),2);});return;}}
   if(held?.typeId==="geumyi:fighter_gauntlet"){
     if(cls(atk)!=="fighter"){ev.cancel=true;system.run(()=>bar(atk,"§c격투가 전용 건틀릿입니다."));return;}
     if(!fighterDamageBypass.has(atk.id)){const stacks=addFury(atk,1);if(stacks>=FIGHTER_FURY_MAX){const amount=ev.damage*1.5,cause=ev.damageSource.cause,impact={x:hurt.location.x,y:hurt.location.y+1,z:hurt.location.z};ev.cancel=true;system.run(()=>{fighterDamageBypass.add(atk.id);safe(()=>hurt.applyDamage(amount,{cause,damagingEntity:atk}));particle(atk.dimension,"minecraft:critical_hit_emitter",impact);sound(atk,"random.sweep",1.25,.6);system.runTimeout(()=>fighterDamageBypass.delete(atk.id),2);});return;}}
   }
 }
 if(hurt.typeId==="minecraft:player"&&!damageBypass.has(hurt.id)&&hurt.hasTag("geumyi_class_fighter")){const b=fighterBonusHp.get(hurt.id)??0;if(b>0){const used=Math.min(b,ev.damage),remain=Math.max(0,ev.damage-used);fighterBonusHp.set(hurt.id,b-used);ev.cancel=true;if(remain>0){const cause=ev.damageSource.cause,damager=atk;system.run(()=>{damageBypass.add(hurt.id);safe(()=>hurt.applyDamage(remain,damager?{cause,damagingEntity:damager}:{cause}));system.runTimeout(()=>damageBypass.delete(hurt.id),2);});}}}
}catch{}});

world.beforeEvents.entityHeal.subscribe(ev=>{try{const p=ev.healedEntity;if(p?.typeId!=="minecraft:player"||cls(p)!=="fighter")return;if(ev.healSource?.cause===EntityHealCause.SelfHeal||ev.healSource?.cause==="SelfHeal")ev.healing=Math.max(0,ev.healing*2);}catch{}});

