world.afterEvents.entityDie.subscribe(ev=>{try{const dead=ev.deadEntity,killer=ev.damageSource?.damagingEntity;if(!dead||judgedSoulIds.delete(dead.id))return;if(!killer||killer.typeId!=="minecraft:player"||cls(killer)!=="reaper")return;if(dead.typeId==="minecraft:player"||dead.typeId==="geumyi:reaper_soul"||dead.typeId==="geumyi:reaper_scythe_projectile"||dead.typeId==="geumyi:reaper_massacre_orbit"||dead.typeId==="minecraft:armor_stand"||dead.typeId==="minecraft:npc")return;const loc={...dead.location},dim=dead.dimension,maxHp=Math.max(1,reaperMaxHealth(dead));spawnReaperSoulDrops(dim,loc,maxHp);}catch{}});
world.afterEvents.entityHurt.subscribe(ev=>{try{const p=ev.damageSource?.damagingEntity;if(!p||p.typeId!=="minecraft:player"||cls(p)!=="reaper"||ev.damageSource?.damagingProjectile)return;if((reaperSkillDamageBypass.get(p.id)??0)>=now())return;const held=safe(()=>p.getComponent("minecraft:equippable")?.getEquipment(EquipmentSlot.Mainhand));if(held?.typeId!=="geumyi:reaper_scythe")return;const n=Number(ev.damage??0);if(n<=0||Math.random()>=.75)return;reaperHeal(p,n*.10,false);particle(p.dimension,REAPER_RED_PARTICLE,{x:p.location.x,y:p.location.y+1.0,z:p.location.z});sound(p,"random.orb",.82,.20);}catch{}});
system.runInterval(()=>{for(const did of["overworld","nether","the_end"]){try{const dim=world.getDimension(did);for(const e of dim.getEntities({type:"geumyi:reaper_soul"})){const l=e.location;reaperSoulBubbleFx(dim,l,e.id.length);}}catch{}}},6);

function explosion(p,loc){particle(p.dimension,"minecraft:huge_explosion_emitter",loc);for(const e of p.dimension.getEntities({location:loc,maxDistance:2.5}))if(targetable(e))damage(e,10,p);sound(p,"random.explode",1);}
function projectileHit(ev,isEntity){try{const p=ev.source,a=ev.projectile,loc=ev.location;if(!p||p.typeId!=="minecraft:player"||!a)return;if(a.typeId==="geumyi:mage_fireball_projectile"){if(isEntity){const e=ev.getEntityHit().entity;if(targetable(e))projectileDamage(e,10,p,a);}particle(p.dimension,"minecraft:huge_explosion_emitter",loc);magicProjectiles.delete(a.id);safe(()=>a.remove());return;}if(a.typeId==="geumyi:magic_bolt_projectile"){if(isEntity){const e=ev.getEntityHit().entity;if(targetable(e))projectileDamage(e,5,p,a);}particle(p.dimension,"minecraft:dragon_breath_trail",loc);magicProjectiles.delete(a.id);safe(()=>a.remove());return;}if(a.typeId==="geumyi:cleric_light_spear"){const st=clericProjectiles.get(a.id);if(isEntity){const e=ev.getEntityHit().entity;if(clericTarget(e)){clericProjectileDamage(e,20,st?.owner??p);hinderByLight(e);}}particle(p.dimension,"minecraft:endrod",loc);particle(p.dimension,"minecraft:villager_happy",{x:loc.x,y:loc.y+.18,z:loc.z});clericProjectiles.delete(a.id);safe(()=>a.remove());return;}if(a.hasTag("geumyi_triple_arrow")){if(isEntity){const e=ev.getEntityHit().entity;if(targetable(e))projectileDamage(e,6,p,a);}safe(()=>a.remove());return;}if(a.hasTag("geumyi_homing_arrow")){const h=homing.get(a.id);if(h&&isEntity){const e=ev.getEntityHit().entity;if(targetable(e)){homing.delete(a.id);projectileDamage(e,4,h.owner??p,a);particle(p.dimension,"minecraft:critical_hit_emitter",loc);}}else homing.delete(a.id);safe(()=>a.remove());return;}if(a.hasTag("geumyi_wire_arrow")){if(dist(p.location,loc)<=22){if(isEntity){const e=ev.getEntityHit().entity;if(targetable(e))projectileDamage(e,35,p,a);}pullPlayer(p,loc);}safe(()=>a.remove());return;}if(a.typeId==="minecraft:arrow"&&!a.hasTag("geumyi_skill_arrow")&&(explosiveUntil.get(p.id)??0)>now()){explosion(p,loc);safe(()=>a.remove());}}catch{}}
world.afterEvents.projectileHitEntity.subscribe(ev=>projectileHit(ev,true));world.afterEvents.projectileHitBlock.subscribe(ev=>projectileHit(ev,false));
system.runInterval(()=>{for(const[id,h]of[...homing.entries()]){try{if(now()-h.born>80||!targetable(h.target)){safe(()=>h.a.remove());homing.delete(id);continue;}const tp=targetPoint(h.target),dx=tp.x-h.a.location.x,dy=tp.y-h.a.location.y,dz=tp.z-h.a.location.z,l=Math.hypot(dx,dy,dz)||1;if(l<=1.20){homing.delete(id);projectileDamage(h.target,4,h.owner,h.a);particle(h.a.dimension,"minecraft:critical_hit_emitter",h.a.location);safe(()=>h.a.remove());continue;}h.a.getComponent("minecraft:projectile")?.shoot({x:dx/l*1.82,y:dy/l*1.82,z:dz/l*1.82});}catch{homing.delete(id);}}},2);
system.runInterval(()=>{for(const[id,m]of[...magicProjectiles.entries()]){try{if(now()-m.born>80){safe(()=>m.a?.remove());magicProjectiles.delete(id);continue;}const l=m.a.location;if(m.type==="geumyi:magic_bolt_projectile"){particle(m.a.dimension,"minecraft:dragon_breath_trail",l);const pc=m.a.getComponent("minecraft:projectile");if(pc&&m.dir)pc.shoot({x:m.dir.x*m.speed,y:m.dir.y*m.speed,z:m.dir.z*m.speed});}else particle(m.a.dimension,"minecraft:basic_flame_particle",l);}catch{magicProjectiles.delete(id);}}},1);
system.runInterval(()=>{for(const[id,m]of[...clericProjectiles.entries()]){try{if(now()-m.born>60){safe(()=>m.a?.remove());clericProjectiles.delete(id);continue;}particle(m.a.dimension,(now()%6<2)?"minecraft:villager_happy":"minecraft:endrod",m.a.location);const pc=m.a.getComponent("minecraft:projectile");if(pc&&m.dir)pc.shoot({x:m.dir.x*m.speed,y:m.dir.y*m.speed,z:m.dir.z*m.speed});}catch{clericProjectiles.delete(id);}}},2);

system.run(()=>world.sendMessage("§a[SKILLS] §fMechanics RPG v1.2.3 시작"));
system.runInterval(()=>{for(const p of world.getAllPlayers()){try{const c=cls(p),sneaking=!!p.isSneaking;if(c==="hero"){const prev=heroSneakPrev.get(p.id)??false;if(sneaking&&!prev)msg(p,`§b[용맹] §f용맹 스택: §e${heroValor(p)}§f/${HERO_VALOR_MAX}`);heroSneakPrev.set(p.id,sneaking);fighterSneakPrev.delete(p.id);}else if(c==="fighter"){const prev=fighterSneakPrev.get(p.id)??false;if(sneaking&&!prev)msg(p,`§6[투지] §f투지 스택: §e${furyState(p).stacks}§f/${FIGHTER_FURY_MAX}`);fighterSneakPrev.set(p.id,sneaking);heroSneakPrev.delete(p.id);}else{heroSneakPrev.delete(p.id);fighterSneakPrev.delete(p.id);}}catch{}}},1);

system.runInterval(()=>{for(const p of world.getAllPlayers()){try{
 if(p.hasTag("geumyi_skill_ui_lock")&&(skillUiUntil.get(p.id)??0)<=now()){skillUiUntil.delete(p.id);safe(()=>p.removeTag("geumyi_skill_ui_lock"));}
 const c=cls(p),prev=classSeen.get(p.id);
 if(prev===undefined){classSeen.set(p.id,c);setClassItemLocks(p,true);}else if(prev!==c){classSeen.set(p.id,c);onClassChanged(p,c);}
 if(p.hasTag("geumyi_refresh_items")){p.removeTag("geumyi_refresh_items");if(c!=="none")giveItems(p,c);msg(p,"§e[TEST] §f전용 장비/스킬 재지급 완료");}
 syncFighterBonus(p);updateFighterFury(p);setClassItemLocks(p,true);
 if(c==="archer"){const eff=p.getEffect("speed");if(!eff||eff.duration<200)p.addEffect("speed",72000,{amplifier:0,showParticles:false});}
 const ex=explosiveUntil.get(p.id)??0;if(ex>0&&ex<=now()){explosiveUntil.delete(p.id);msg(p,"§7폭발 화살 효과가 종료되었습니다. 남은 쿨타임은 30초입니다.");}
 const ps=assassinPrepStealthUntil.get(p.id)??0;if(ps>0&&ps<=now())assassinPrepStealthUntil.delete(p.id);
 const fu=fighterLimitUntil.get(p.id)??0;if(fu>0&&fu<=now())finishFighterLimit(p);
 const hg=heroGuardUntil.get(p.id)??0;if(hg>0&&hg<=now())endHeroGuard(p);
 const hp=heroParryUntil.get(p.id)??0;if(hp>0&&hp<=now())heroParryUntil.delete(p.id);
 const rf=reaperFlipState.get(p.id)??0;if(rf>0&&rf<=now())reaperFlipState.delete(p.id);
 const ro=reaperJudgmentOverflow.get(p.id);if(ro&&ro.until<=now())reaperJudgmentOverflow.delete(p.id);
}catch{}}},10);
